import * as THREE from 'three';
import { getSlider, RendererThree } from '../../../../lib';
import { dataFromRhino } from '../LAB_Web_11_MeshRhinoGeo';

import { FBXLoader } from 'three/examples/jsm/loaders/FBXLoader.js';

import { MeshGradient, colorMaps, ColorMapType } from './MeshGradient/MeshGradient';

export class Solution extends RendererThree {
	dirLight: THREE.DirectionalLight;

	meshGradient: MeshGradient;

	constructor(id: string = 'main') {
		super(id);

		this.meshGradient = new MeshGradient({ scene: this.scene});

		this.renderer.localClippingEnabled = true;
		const divUI = document.createElement('div');
		divUI.style.position = 'absolute';
		this.hostDiv.append(divUI);

		const loadObjBtn = document.createElement('button');
		loadObjBtn.id = 'loadObjBtn';
		loadObjBtn.textContent = 'Load OBJ';
		// loadObjBtn.style.position = 'absolute';

		const fileInput = document.createElement('input');
		fileInput.type = 'file';
		fileInput.id = 'fileInput';
		fileInput.accept = '.obj,.fbx';
		fileInput.style.display = 'none';

		loadObjBtn.addEventListener('click', () => {
			fileInput.click();
		});

		fileInput.addEventListener('change', (event) => {
			const file = event.target.files[0];
			if (!file) return;

			const extension = file.name.split('.').pop().toLowerCase();

			if (extension === 'obj') {
				const reader = new FileReader();
				reader.onload = (e) => {
					const objText = e.target.result;
					// console.log(objText);
					this.meshGradient.initByOBJ(objText);
				};
				reader.onerror = () => {
					console.error('fail to load the OBJ');
				};

				reader.readAsText(file);
				
			} else if (extension === 'fbx') {
				
				const fbxLoader = new FBXLoader();
				const fileURL = URL.createObjectURL(file);

				let zUp = true;
				
				fbxLoader.load(
					fileURL,
					(fbx) => {
						const vertices = [];
						const faces = [];
						const scale = 0.1;
						
						if (zUp) {
							// fbx.rotation.x = Math.PI / 2;
						}
						
						fbx.traverse((child) => {
							if (child.isMesh && child.geometry) {
								const geometry = child.geometry;
								const positions = geometry.attributes.position.array;
								const indices = geometry.index ? geometry.index.array : null;
								
								const vertexOffset = vertices.length;
								
								for (let i = 0; i < positions.length; i += 3) {
									vertices.push([
										positions[i] * scale,
										positions[i + 1] * scale,
										positions[i + 2] * scale
									]);
								}
								
								if (indices) {
									for (let i = 0; i < indices.length; i += 3) {
										faces.push([
											indices[i] + vertexOffset,
											indices[i + 1] + vertexOffset,
											indices[i + 2] + vertexOffset
										]);
									}
								} else {
									const numVertices = positions.length / 3;
									for (let i = 0; i < numVertices; i += 3) {
										if (i + 2 < numVertices) {
											faces.push([
												vertexOffset + i,
												vertexOffset + i + 1,
												vertexOffset + i + 2
											]);
										}
									}
								}
							}
						});
						
						URL.revokeObjectURL(fileURL);
						
						if (vertices.length > 0 && faces.length > 0) {
							this.meshGradient.createMeshFromData(vertices, faces);
						}
					},
					(progress) => {
						if (progress.lengthComputable) {
							const percent = (progress.loaded / progress.total) * 100;
							// console.log(`FBX loading: ${percent.toFixed(1)}%`);
						}
					},
					(error) => {
						console.error('FBX fail to load:', error);
						URL.revokeObjectURL(fileURL);
					}
				);
				
			} else {
				console.error(`no support file: ${extension}`);
			}
		});


		divUI.append(loadObjBtn);
		divUI.append(fileInput);

		const slTypeSpeed = getSlider('ani', 0.0, 100);
		slTypeSpeed.slider.defaultValue = '10';
		divUI.appendChild(slTypeSpeed.div);
		slTypeSpeed.slider.oninput = () => {
			const value = parseInt(slTypeSpeed.slider.value) * 0.01;
			this.meshGradient.speed = value;
		};

		const slTypeMin = getSlider(`min:${this.meshGradient.min}`, -300, 300);
		slTypeMin.slider.defaultValue = `${this.meshGradient.min}`;
		divUI.appendChild(slTypeMin.div);
		slTypeMin.slider.oninput = () => {
			const value = parseInt(slTypeMin.slider.value) * 0.01;
			this.meshGradient.min = value;
			slTypeMin.text.textContent = `min:${value.toFixed(2)}`;
		};
		const slTypeMax = getSlider(`max:${this.meshGradient.max}`, -300, 300);
		slTypeMax.slider.defaultValue = `${this.meshGradient.max}`;
		divUI.appendChild(slTypeMax.div);
		slTypeMax.slider.oninput = () => {
			const value = parseInt(slTypeMax.slider.value) * 0.01;
			this.meshGradient.max = value;
			slTypeMax.text.textContent = `max:${value.toFixed(2)}`;
		};

		const slTypeClippingX = getSlider(`Clipping X`, -200, 200);
		slTypeClippingX.slider.defaultValue = `${200}`;
		divUI.appendChild(slTypeClippingX.div);
		slTypeClippingX.slider.oninput = () => {
			const value = parseInt(slTypeClippingX.slider.value) * 0.01;
			this.meshGradient.clipX = value
		};

		const slTypeClippingY = getSlider(`Clipping Y`, -200, 200);
		slTypeClippingY.slider.defaultValue = `${200}`;
		divUI.appendChild(slTypeClippingY.div);
		slTypeClippingY.slider.oninput = () => {
			const value = parseInt(slTypeClippingY.slider.value) * 0.01;
			this.meshGradient.clipY = value
		};

		// .............................................................

		const keys = Object.keys(ColorMapType);
		const header = document.createElement('div');
		header.className = 'header';
		const slider = document.createElement('input');
		slider.type = 'range';
		slider.min = '0';
		slider.max = `${keys.length - 1}`;
		slider.value = '0';
		slider.style.width = '100px';

		const nameEl = document.createElement('div');
		nameEl.className = 'name';
		header.appendChild(nameEl);

		const controls = document.createElement('div');
		controls.className = 'controls';

		const hexList = document.createElement('div');
		hexList.className = 'hexList';

		// divUI에 붙이기
		divUI.appendChild(header);
		divUI.appendChild(slider);
		divUI.appendChild(controls);

		divUI.appendChild(hexList);

		// 함수
		const updateUI = () => {
			const idx = Number(slider.value);
			const key = keys[idx];
			const map = colorMaps[ColorMapType[key]];
			// console.log({ idx, keys, key, map });

			nameEl.textContent = key;
			// indexLabel.textContent = `${idx + 1} / ${keys.length}`;
			// const hexColors = map.map((entry) => `#${entry.color.getHexString()}`);
			// hexList.textContent = hexColors.join('  •  ');

			// console.log({ key });

			this.meshGradient.initMat(ColorMapType[key]);
		};
		slider.addEventListener('input', updateUI);
		// updateUI();

		this.initMesh();
	}
	public initMesh() {
		const vertices = [];
		const faces = [];

		const scale = 0.1;

		for (let i = 0; i < dataFromRhino['v'].length; ++i) {
			const pos = dataFromRhino['v'][i];
			vertices.push([+pos[0] * scale, +pos[2] * scale, +pos[1] * scale]);
		}

		for (let i = 0; i < dataFromRhino['f'].length; ++i) {
			const pos = dataFromRhino['f'][i];
			faces.push([pos[2], pos[1], pos[0]]);
		}

		if (vertices.length > 0 && faces.length > 0) {
			this.meshGradient.createMeshFromData(vertices, faces);
		}

		this.start();
	}
	

	public update(scene: THREE.Scene) {
		// if (this.mesh) {
		// 	this.time += this.speed * 0.01;
		// 	this.mesh.material.uniforms.time.value = this.time;
		// }
		this.meshGradient.update()
	}

}
